def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count recent outcomes
    my_last = history[-1][0]
    op_last = history[-1][1]

    # Detect opponent's tendency
    if n >= 10:
        # Count opponent defections in last 10 rounds
        op_defects = sum(1 for h in history[-10:] if h[1] == 'D')
        my_defects = sum(1 for h in history[-10:] if h[0] == 'D')

        # If opponent is heavily defecting, retaliate
        if op_defects >= 7:
            return 'D'
        # If opponent is mostly cooperating, cooperate
        if op_defects <= 2:
            return 'C'

    # Opening: cooperate for first few rounds
    if n < 5:
        return 'C'

    # Tit-for-tat with occasional forgiveness
    if op_last == 'D':
        # Retaliate but sometimes forgive to avoid death spirals
        if n >= 20:
            recent_op_defects = sum(1 for h in history[-20:] if h[1] == 'D')
            if recent_op_defects > 15:
                # Opponent is relentless, defect back
                return 'D'
            # Otherwise probe with defection occasionally
            if rng.random() < 0.1:
                return 'C'
        return 'D'
    else:
        # Opponent cooperated last round
        # Occasionally exploit a very cooperative opponent
        if n >= 30:
            recent_op_defects = sum(1 for h in history[-30:] if h[1] == 'D')
            if recent_op_defects <= 3 and rng.random() < 0.05:
                return 'D'
        return 'C'
